sys_script.script:
(function executeRule(current, previous /*null when async*/) {

		var gr = new GlideRecord('x_hsb11_hsbcmss_eh_hsbc_email_case');
		gr.get(current.parent_email_case);
		gr.state="2";
		gr.update();

		var grt = new GlideRecord('x_hsb11_hsbcmss_eh_hsbc_email_case_task');
			grt.addQuery('parent',current.parent_email_case);
			grt.addQuery('state','IN','1,2');
			grt.addQuery('task_type','Manually Process Email');
			grt.query();
			if(!grt.hasNext()){
				var grn = new GlideRecord('x_hsb11_hsbcmss_eh_hsbc_email_case_task');
				var mocs_group = gs.getProperty('x_hsb11_hsbc_mss_t.hsbc.assignment.group.mocs');
				grn.initialize();
				grn.task_type="Manually Process Email";
				grn.short_description="Error while trying to update Trade Data in ServiceNow: "+ current.system_response.toString();
				grn.parent=current.parent_email_case;
				grn.qtrack_id=current.parent_email_case.qtrack_id;
				grn.swb_id=current.parent_email_case.swb_id;
				grn.assignment_group = mocs_group;
				grn.state='1';
				grn.entity=current.parent_email_case.entity;
				grn.insert();
			}

})(current, previous);
